import { Cache } from "./vendor/cache.mjs";
export function openSession() {
  const session = { closed: false, renders: 0, cache: new Cache() };
  session.unsubscribe = session.cache.onEvict(() => {
    if (session.closed) throw new Error("render after close");
    session.renders += 1;
  });
  return session;
}

files.vendor/cache.mjs:
export class Cache {
  constructor() { this.entries = new Map(); this.listeners = new Set(); }
  put(key, value, expiresAt) { this.entries.set(key, { value, expiresAt }); }
  onEvict(listener) { this.listeners.add(listener); return () => this.listeners.delete(listener); }
  gc(now) {
    for (const [key, entry] of this.entries) {
      if (entry.expiresAt > now) continue;
      this.entries.delete(key);
      for (const listener of this.listeners) listener(key);
    }
  }
}

